mapper.select:
SELECT A.SALES_ID AS salesId , A.CUST_ID AS custId , A.EMP_ID AS salesUserId , A.SALES_TITLE AS salesTitle , A.EXPECTED_AMT AS expectedAmt , A.STATUS AS status , A.PROBABILITY AS probability , B.CUST_NM AS custNm , B.CEO_NM AS ceoNm , C.EMP_NM AS salesNm FROM TB_SALES A LEFT JOIN TB_CUSTOMER B ON A.CUST_ID = B.CUST_ID LEFT JOIN TB_EMP C ON A.EMP_ID = C.EMP_ID WHERE A.DEL_YN = 'N'
AND A.SALES_TITLE LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.SALES_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_SALES (
    CUST_ID, EMP_ID, SALES_TITLE, EXPECTED_AMT, EXPECTED_DT, PROBABILITY, STATUS, SALES_CONTENT
) VALUES (
    #{custId}, #{salesUserId}, #{salesTitle}, #{expectedAmt}, NULLIF(#{expectedDt},''), #{probability}, #{status}, #{salesContent}
)

mapper.update:
UPDATE TB_SALES SET
      EMP_ID = #{salesUserId}
    , SALES_TITLE = #{salesTitle}
    , EXPECTED_AMT = #{expectedAmt}
    , EXPECTED_DT = NULLIF(#{expectedDt},'')
    , PROBABILITY = #{probability}
    , STATUS = #{status}
    , SALES_CONTENT = #{salesContent}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE SALES_ID = #{salesId}

UPDATE TB_SALES SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE SALES_ID = #{salesId}

UPDATE TB_SALES 
   SET STATUS = #{status}
 WHERE SALES_ID = #{selectedId}

UPDATE TB_SALES
   SET ATCH_FILE_ID = #{atchFileId}
 WHERE SALES_ID = #{salesId}
